<section class="roster">
  <header class="roster__header">
    <h1 hlmH1>Roster</h1>
    <p hlmMuted>Every hero on the books. Example data.</p>
  </header>

  <div class="roster__filters">
    <label hlmLabel for="roster-search" class="roster__label">Search heroes</label>
    <input
      hlmInput
      #search
      id="roster-search"
      type="search"
      placeholder="Search name, alias or ID"
      class="roster__search"
      (input)="vm.setQuery(search.value)"
    />

    <hlm-select [value]="vm.classFilter()" (valueChange)="vm.setClassFilter($event)">
      <hlm-select-trigger class="roster__class-trigger" aria-label="Filter by power class">
        <hlm-select-value />
      </hlm-select-trigger>
      <hlm-select-content *hlmSelectPortal>
        <hlm-select-group>
          @for (option of vm.classOptions; track option.value) {
            <hlm-select-item [value]="option.value">{{ option.label }}</hlm-select-item>
          }
        </hlm-select-group>
      </hlm-select-content>
    </hlm-select>

    <a hlmBtn routerLink="/recruit" class="roster__recruit">
      <ng-icon hlmIcon name="lucideUserPlus" />
      Recruit
    </a>
  </div>

  <!-- 375px: the table scrolls inside its own container, so the page never does. -->
  <div hlmTableContainer class="roster__scroll">
    <table hlmTable>
      <caption hlmTableCaption class="roster__caption">Heroes, strongest first</caption>
      <thead hlmTableHeader>
        <tr hlmTableRow>
          <th hlmTableHead scope="col">Hero</th>
          <th hlmTableHead scope="col">Class</th>
          <th hlmTableHead scope="col">Power</th>
          <th hlmTableHead scope="col">Status</th>
          <th hlmTableHead scope="col">Clearance</th>
          <th hlmTableHead scope="col" class="roster__actions-head">Actions</th>
        </tr>
      </thead>
      <tbody hlmTableBody>
        @for (row of vm.rows(); track row.hero.id) {
          <tr hlmTableRow>
            <td hlmTableCell>
              <div class="roster__hero">
                <hlm-avatar size="sm" aria-hidden="true">
                  <span hlmAvatarFallback>{{ row.initials }}</span>
                </hlm-avatar>
                <div class="roster__identity">
                  <span hlmSmall>{{ row.hero.name }}</span>
                  <span hlmMuted>{{ row.hero.id }}</span>
                </div>
              </div>
            </td>
            <td hlmTableCell>
              <span hlmBadge variant="outline">{{ row.hero.powerClass }}</span>
            </td>
            <td hlmTableCell>{{ row.hero.powerIndex }}</td>
            <td hlmTableCell>
              <span hlmBadge [variant]="row.statusVariant">{{ row.hero.status }}</span>
            </td>
            <td hlmTableCell>Tier {{ row.hero.clearanceTier }}</td>
            <td hlmTableCell>
              <a
                hlmBtn
                variant="ghost"
                size="icon-sm"
                [routerLink]="['/detail', row.hero.id]"
                [attr.aria-label]="'Edit ' + row.hero.name"
              >
                <ng-icon hlmIcon name="lucidePencil" />
              </a>
            </td>
          </tr>
        } @empty {
          <tr hlmTableRow>
            <td hlmTableCell colspan="6" class="roster__empty">No heroes match these filters.</td>
          </tr>
        }
      </tbody>
    </table>
  </div>

  <footer class="roster__footer">
    <p hlmSmall aria-live="polite">{{ vm.visibleCount() }} of {{ vm.totalCount() }} heroes</p>
    <p hlmMuted>Sorted by power</p>
  </footer>
</section>
=== src/app/forms/form-field-meta.ts
/**
 * Presentation metadata that rides on a zod field via `.meta()`. Strongly typed,
 * so a missing label is a compile error rather than a runtime surprise. A form
 * component reads this off the schema instead of restating labels and control
 * kinds in a parallel config object.
 */
export type ControlKind = 'text' | 'email' | 'number' | 'select' | 'checkbox' | 'textarea';

export interface FormFieldMeta {
  label: string;
  control: ControlKind;
  placeholder?: string;
  options?: ReadonlyArray<{ value: string; label: string }>;
  order?: number;
  help?: string;
}
=== src/app/forms/zod-meta.ts
import type { z } from 'zod';
import type { FormFieldMeta } from './form-field-meta';

/**
 * Read the FormFieldMeta off each field of a zod object schema. Keeps the label,
 * control kind, and placeholder on the schema (one source of truth) so a form
 * component reads them instead of restating them. Pair with `validateStandardSchema`
 * from `@angular/forms/signals` for validation, so shape, rules, and labels all
 * live on the one schema.
 */
export function formMeta(schema: z.ZodObject<z.ZodRawShape>): Record<string, FormFieldMeta> {
  const meta: Record<string, FormFieldMeta> = {};
  for (const [name, field] of Object.entries(schema.shape)) {
    meta[name] = (field as z.ZodType).meta() as unknown as FormFieldMeta;
  }
  return meta;
}
